const stop = (video) => {
  if (video.dataset.claymodStopped) return;
  video.dataset.claymodStopped = "1";
  video.autoplay = false;
  video.removeAttribute("autoplay");
  video.pause();
};
document.querySelectorAll("video[autoplay]").forEach(stop);
new MutationObserver(() => {
  document.querySelectorAll("video[autoplay]").forEach(stop);
}).observe(document.documentElement, { childList: true, subtree: true });
